start=s.index('    private void showTabletMeasurements() {'); end=s.index('    private LinearLayout tabletMeasurementRow',start)
method='''    private void showTabletMeasurements() {\n        clearBody("Měření", "OBVOD / PRVEK → měřicí body → spojitost → RCD / RCBO"); addRevisionContext();\n        List<Db.Row> all=db.measurements(revisionId), rows=new ArrayList<>(); for(Db.Row r:all)if(!"BLANK".equals(measurementRowType(r)))rows.add(r);\n        LinearLayout columns=tabletColumns(); LinearLayout list=tabletPanel(columns,6), detail=tabletPanel(columns,5);\n        LinearLayout top=new LinearLayout(this);top.setOrientation(LinearLayout.HORIZONTAL);top.addView(smallButton("＋ NOVÝ OBVOD / PRVEK",C_ORANGE,C_TEXT,v->measurementDialog(null,"CIRCUIT")),new LinearLayout.LayoutParams(0,dp(48),2));LinearLayout bl=new LinearLayout.LayoutParams(0,dp(48),1);bl.leftMargin=dp(7);top.addView(smallButton("HROMADNĚ",C_DARK,Color.WHITE,v->bulkDialog()),bl);list.addView(top,marginBottom(dp(10)));\n        if(rows.isEmpty()){LinearLayout hint=card();hint.addView(text("MĚŘENÍ ZAČÍNÁ OBVODEM / PRVKEM",15,C_TEXT,true));hint.addView(text("Nejdříve založ obvod nebo zařízení. Potom k němu přidávej měřicí body, spojitost a RCD / RCBO.",14,C_MUTED,false),marginTop(dp(7)));list.addView(hint);detail.addView(text("Zatím není vytvořen žádný obvod ani prvek.",17,C_MUTED,false));return;}\n        Map<String,List<Db.Row>> children=new LinkedHashMap<>();List<Db.Row> roots=new ArrayList<>();for(Db.Row r:rows){String pk=nz(r.get("parent_key"));Db.Row parent=null;if(!pk.isEmpty())for(Db.Row x:rows)if(pk.equals(nz(x.get("item_key")))){parent=x;break;}if(parent==null)roots.add(r);else{List<Db.Row> kids=children.get(nodeKey(parent));if(kids==null){kids=new ArrayList<>();children.put(nodeKey(parent),kids);}kids.add(r);}}\n        Db.Row active=null;for(Db.Row r:rows)if(r.id()==selectedMeasurementId){active=r;break;}if(active==null){active=roots.get(0);selectedMeasurementId=active.id();}\n        for(Db.Row root:roots)addTabletMeasurementGroup(list,root,children,root.id()==selectedMeasurementId);\n        final Db.Row chosen=active;String title=nz(chosen.get("element"));if(title.isEmpty())title=rowTypeLabel(measurementRowType(chosen));detail.addView(text(title,22,C_TEXT,true),marginBottom(dp(4)));detail.addView(pill(rowTypeLabel(measurementRowType(chosen)),rowTypeColor(measurementRowType(chosen)),Color.WHITE),marginBottom(dp(12)));\n        String kind=measurementRowType(chosen);Db.Row owner=chosen;if(!isTreeParent(kind)&&!nz(chosen.get("parent_key")).isEmpty())for(Db.Row x:rows)if(nz(chosen.get("parent_key")).equals(nz(x.get("item_key")))){owner=x;break;}\n        if(isTreeParent(measurementRowType(owner))){final Db.Row parent=owner;detail.addView(text("Přidat měření k: "+(nz(parent.get("element")).isEmpty()?"prvku":parent.get("element")),14,C_MUTED,true),marginBottom(dp(7)));addMeasurementQuickActions(detail,parent);List<Db.Row> kids=children.get(nodeKey(parent));if(kids==null||kids.isEmpty())detail.addView(text("Tento prvek zatím nemá žádná měření.",14,C_MUTED,false),marginTop(dp(10)));else{detail.addView(text("Měření tohoto prvku",14,C_MUTED,true),marginTop(dp(12)));for(Db.Row child:kids){LinearLayout c=card();c.setClickable(true);c.setOnClickListener(v->{selectedMeasurementId=child.id();showMeasurements(false);});String ct=nz(child.get("element"));if(ct.isEmpty())ct=rowTypeLabel(measurementRowType(child));c.addView(text(ct,15,C_TEXT,true));String cv=valuesText(child);if(cv.isEmpty())cv="Zatím bez naměřené hodnoty";c.addView(text(cv,13,C_MUTED,false),marginTop(dp(4)));detail.addView(c,marginBottom(dp(6)));}}}\n        else{LinearLayout values=measurementValueGrid(chosen);if(values.getChildCount()>0)detail.addView(values,marginBottom(dp(10)));else detail.addView(text("Hodnoty zatím nejsou vyplněné.",14,C_MUTED,false),marginBottom(dp(10)));if(!nz(chosen.get("note")).isEmpty())detail.addView(text("Poznámka: "+chosen.get("note"),14,C_MUTED,false),marginBottom(dp(10)));}\n        detail.addView(smallButton("UPRAVIT VYBRANOU POLOŽKU",C_ORANGE,C_TEXT,v->measurementDialog(chosen)),marginBottom(dp(8)));detail.addView(smallButton("SMAZAT VYBRANOU POLOŽKU",Color.WHITE,C_RED,v->new AlertDialog.Builder(this).setTitle("Smazat položku?").setMessage("Smazat vybranou položku měření?").setNegativeButton("Ne",null).setPositiveButton("Ano",(d,w)->{db.deleteMeasurement(chosen.id());selectedMeasurementId=0;showMeasurements(false);}).show()),marginBottom(dp(8)));\n    }\n    private void addMeasurementQuickActions(LinearLayout detail,Db.Row parent){String[] labels={"＋ MĚŘICÍ BOD","＋ SPOJITOST","＋ RCD / RCBO","＋ POZNÁMKA"};String[] types={"POINT","CONTINUITY","RCD","NOTE"};for(int row=0;row<2;row++){LinearLayout line=new LinearLayout(this);line.setOrientation(LinearLayout.HORIZONTAL);for(int col=0;col<2;col++){int i=row*2+col;final String t=types[i];LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);if(col>0)lp.leftMargin=dp(7);line.addView(smallButton(labels[i],C_BG,C_TEXT,v->measurementDialog(null,t,parent)),lp);}detail.addView(line,marginBottom(dp(7)));}}\n    private void addTabletMeasurementGroup(LinearLayout list,Db.Row root,Map<String,List<Db.Row>> children,boolean selected){String rt=measurementRowType(root);List<Db.Row> kids=children.get(nodeKey(root));LinearLayout c=card();c.setClickable(true);c.setOnClickListener(v->{selectedMeasurementId=root.id();showMeasurements(false);});c.setBackground(rounded(selected?Color.rgb(255,243,220):Color.WHITE,selected?C_ORANGE:C_BORDER,12));LinearLayout head=new LinearLayout(this);head.setOrientation(LinearLayout.HORIZONTAL);head.setGravity(Gravity.CENTER_VERTICAL);LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);String title=nz(root.get("element"));if(title.isEmpty())title="NOVÝ PRVEK";tx.addView(text(title,16,C_TEXT,true));int total=kids==null?0:kids.size(),done=0;if(kids!=null)for(Db.Row k:kids)if(k.bool("done"))done++;tx.addView(text(total==0?"Zatím bez měření":done+" / "+total+" podřízených měření hotovo",12,C_MUTED,false));head.addView(tx,new LinearLayout.LayoutParams(0,dp(50),1));head.addView(pill(rowTypeLabel(rt),rowTypeColor(rt),Color.WHITE),new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT,dp(28)));c.addView(head);if(kids!=null&&!kids.isEmpty()){LinearLayout summary=new LinearLayout(this);summary.setOrientation(LinearLayout.VERTICAL);summary.setPadding(dp(8),dp(6),dp(8),0);for(Db.Row k:kids){String t=nz(k.get("element"));if(t.isEmpty())t=rowTypeLabel(measurementRowType(k));String v=valuesText(k);if(v.isEmpty())v="—";TextView line=text("↳ "+t+"   "+v,12,C_TEXT,false);line.setMaxLines(2);summary.addView(line,marginBottom(dp(4)));}c.addView(summary);}list.addView(c,marginBottom(dp(8)));}\n\n'''
